export default {"html":"<p data-line=\"0\" class=\"code-line\">Firebase v9 added tree-shaking support.</p>\n<p data-line=\"2\" class=\"code-line\">Reference:</p>\n<p data-line=\"4\" class=\"code-line\"><a href=\"https://qiita.com/qrusadorz/items/166aa1948dca8bd046a0\" target=\"_blank\" rel=\"noopener noreferrer\">https://qiita.com/qrusadorz/items/166aa1948dca8bd046a0</a></p>\n<p data-line=\"6\" class=\"code-line\">That came with breaking syntax changes to enable tree-shaking. Covering everything is hard, but here is how to update within the Firebase Authentication scope.</p>\n<h2 id=\"the-lazy-upgrade\" data-line=\"8\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#the-lazy-upgrade\" aria-hidden=\"true\"></a> The Lazy Upgrade</h2>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"10\"><span class=\"line\"><span>ng update @angular/fire firebase</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"15\" class=\"code-line\">This does upgrade the packages. If you inspect what changed, you should see imports move from <code>@angular/fire/**</code> to <code>@angular/fire/compat</code>. \"Compat\" means compatibility: it only adds backward-compatible entry points, so <strong>the package version goes up, but you still cannot tree-shake.</strong> Also, compat will not stay around forever, so treat it as a stopgap.</p>\n<h2 id=\"the-proper-upgrade\" data-line=\"17\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#the-proper-upgrade\" aria-hidden=\"true\"></a> The Proper Upgrade</h2>\n<p data-line=\"19\" class=\"code-line\">You need to change the syntax to support tree-shaking.</p>\n<h3 id=\"installing-in-the-module\" data-line=\"21\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#installing-in-the-module\" aria-hidden=\"true\"></a> Installing in the Module</h3>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"23\"><span class=\"line\"><span>+ import { getApp, provideFirebaseApp, initializeApp } from '@angular/fire/app';</span></span>\n<span class=\"line\"><span>+ import {</span></span>\n<span class=\"line\"><span>+   getAuth,</span></span>\n<span class=\"line\"><span>+   provideAuth,</span></span>\n<span class=\"line\"><span>+ } from '@angular/fire/auth';</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span>  @NgModule({</span></span>\n<span class=\"line\"><span>    declarations: [AppComponent],</span></span>\n<span class=\"line\"><span>    imports: [</span></span>\n<span class=\"line\"><span>      BrowserModule,</span></span>\n<span class=\"line\"><span>      IonicModule.forRoot(),</span></span>\n<span class=\"line\"><span>      AppRoutingModule,</span></span>\n<span class=\"line\"><span>-     AngularFireAuthModule,</span></span>\n<span class=\"line\"><span>+     provideFirebaseApp(() =&gt; initializeApp(environment.firebase)),</span></span>\n<span class=\"line\"><span>+     provideAuth(() =&gt; getAuth()),</span></span>\n<span class=\"line\"><span>      ...</span></span>\n<span class=\"line\"><span>    ],</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"44\" class=\"code-line\">The large <code>AngularFireAuthModule</code> is gone. You now split Firebase app setup into <code>provideFirebaseApp</code> and auth setup into <code>provideAuth</code>.</p>\n<p data-line=\"46\" class=\"code-line\">However, this alone causes auth issues on Capacitor iOS:<br>\n<a href=\"https://github.com/angular/angularfire/issues/3087\" target=\"_blank\" rel=\"noopener noreferrer\">https://github.com/angular/angularfire/issues/3087</a></p>\n<p data-line=\"49\" class=\"code-line\">So when you use Capacitor natively, add that branch. Capacitor's <code>isNativePlatform()</code> can detect the platform:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"51\"><span class=\"line\"><span>import { getApp, provideFirebaseApp, initializeApp } from '@angular/fire/app';</span></span>\n<span class=\"line\"><span>import {</span></span>\n<span class=\"line\"><span>  getAuth,</span></span>\n<span class=\"line\"><span>  indexedDBLocalPersistence,</span></span>\n<span class=\"line\"><span>  initializeAuth,</span></span>\n<span class=\"line\"><span>  provideAuth,</span></span>\n<span class=\"line\"><span>} from '@angular/fire/auth';</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span>...</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span>    provideFirebaseApp(() =&gt; initializeApp(environment.firebase)),</span></span>\n<span class=\"line\"><span>    provideAuth(() =&gt; {</span></span>\n<span class=\"line\"><span>      if (Capacitor.isNativePlatform()) {</span></span>\n<span class=\"line\"><span>        return initializeAuth(getApp(), {</span></span>\n<span class=\"line\"><span>          persistence: indexedDBLocalPersistence,</span></span>\n<span class=\"line\"><span>        });</span></span>\n<span class=\"line\"><span>      } else {</span></span>\n<span class=\"line\"><span>        return getAuth();</span></span>\n<span class=\"line\"><span>      }</span></span>\n<span class=\"line\"><span>    }),</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"75\" class=\"code-line\">On native platforms, set <code>indexedDBLocalPersistence</code> as <code>persistence</code> during initialization.</p>\n<h3 id=\"writing-login-code\" data-line=\"77\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#writing-login-code\" aria-hidden=\"true\"></a> Writing Login Code</h3>\n<p data-line=\"79\" class=\"code-line\">First, instead of injecting <code>AngularFireAuth</code>, inject <code>Auth</code> from <code>@angular/fire/auth</code>:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"81\"><span class=\"line\"><span>- import { AngularFireAuth } from '@angular/fire/compat/auth';</span></span>\n<span class=\"line\"><span>+ import { Auth } from '@angular/fire/auth';</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span>   constructor(</span></span>\n<span class=\"line\"><span>-    private afAuth: AngularFireAuth,</span></span>\n<span class=\"line\"><span>+    private afAuth: Auth,</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"91\" class=\"code-line\">That is the important part. After that, the rule is to call the methods that used to hang off <code>AngularFireAuth</code> directly and pass <code>Auth</code> as the first argument.</p>\n<p data-line=\"93\" class=\"code-line\">For example, <code>authState</code> becomes:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"95\"><span class=\"line\"><span>+ import { authState } from '@angular/fire/auth';</span></span>\n<span class=\"line\"><span>...</span></span>\n<span class=\"line\"><span>-    this.afAuth.authState.pipe(...</span></span>\n<span class=\"line\"><span>+    authState(this.afAuth).pipe(...</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"103\" class=\"code-line\">Instead of calling <code>authState</code> on <code>this.afAuth</code>, import and call <code>authState</code> directly and pass <code>this.afAuth</code> as the first argument. There are a few exceptions, maybe less than 10%, but more than 90% of methods can be updated this way.</p>\n<p data-line=\"105\" class=\"code-line\">Here are several migration examples:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"107\"><span class=\"line\"><span>-    return this.afAuth.authState;</span></span>\n<span class=\"line\"><span>+    return authState(this.afAuth);</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"113\"><span class=\"line\"><span>-   await this.afAuth.createUserWithEmailAndPassword(email, password)</span></span>\n<span class=\"line\"><span>+   await createUserWithEmailAndPassword(this.afAuth, email, password).catch(</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"119\"><span class=\"line\"><span>-    await this.afAuth.signInWithEmailAndPassword(email, password)</span></span>\n<span class=\"line\"><span>-      .catch(async (error) =&gt; {</span></span>\n<span class=\"line\"><span>+    await signInWithEmailAndPassword(this.afAuth, email, password).catch(</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"126\"><span class=\"line\"><span>-    await this.afAuth.sendPasswordResetEmail(email).catch(async (error) =&gt; {</span></span>\n<span class=\"line\"><span>+    await sendPasswordResetEmail(this.afAuth, email).catch(async (error) =&gt; {</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"132\"><span class=\"line\"><span>-        await this.afAuth.sendPasswordResetEmail(email);</span></span>\n<span class=\"line\"><span>+        await sendPasswordResetEmail(this.afAuth, email);</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"138\"><span class=\"line\"><span>-    await user.sendEmailVerification().catch(async (error) =&gt; {</span></span>\n<span class=\"line\"><span>+    await sendEmailVerification(user).catch(async (error) =&gt; {</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"144\" class=\"code-line\">Simple, right? See you next time.</p>\n","headings":[{"id":"the-lazy-upgrade","text":"The Lazy Upgrade","level":2},{"id":"the-proper-upgrade","text":"The Proper Upgrade","level":2},{"id":"installing-in-the-module","text":"Installing in the Module","level":3},{"id":"writing-login-code","text":"Writing Login Code","level":3}]} as const;
